#!/usr/bin/env python3
"""Compile SEC86 pure SCSI planner and independent wire-format/refusal oracles."""
import argparse, hashlib, json, os, subprocess, time
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
REQUIRED=['tur_ready_no_buffer', 'standard_inquiry_real_single_direct_disk', 'vpd_supported_serial_device_identifier_lengths', 'metadata_truncation_obeys_allocation_and_cpu_span', 'capacity10_exact_admitted_geometry', 'capacity16_same_geometry_and_block_size', 'mode_sense6_10_writeback_cache_without_false_read_fua_or_dpo_support', 'report_luns_only_lun_zero', 'request_sense_fixed_format_no_sense', 'read10_plan_does_not_fabricate_or_copy_sectors', 'read16_last_sector_safe_translation', 'read6_12_single_sector_compatibility', 'zero_block_reads_are_noop_without_data_direction', 'range_and_64bit_overflow_refused', 'count_size_mismatch_and_read6_zero_256_refused', 'data_direction_exact_span_and_null_mapping_refused', 'nonallowlisted_media_mutations_and_data_out_write_protected', 'all_opcode_scan_cannot_expand_hardware_read_whitelist', 'unsupported_opcode_device_check_condition', 'read_fua_dpo_refused_not_silently_discarded', 'service_action_and_reserved_field_validation', 'write10_16_ntfs_start_payload_is_never_mutated_by_planner', 'write_fua_explicit_flag_requires_device_flush_before_success', 'write_reserved_protection_dpo_fua_nv_flags_refused_exhaustively', 'write_group_control_linked_commands_refused', 'write_exact_cdb_length_required', 'write_unidirectional_data_out_required', 'write_exact_mapped_cpu_payload_required', 'write_count_size_mismatch_and_overflow_never_expand_fence', 'write_ntfs_extent_neighbors_denied_before_runtime_admission', 'write10_16_64g_final_backup_sector_admitted_without_truncation', 'write_gpt_and_disk_tail_denied', 'write64_high_lba_cannot_truncate_into_allowed_target', 'write_zero_count_is_no_media_operation_and_has_no_payload', 'sync10_16_zero_count_is_real_whole_device_flush_not_noop', 'sync_valid_final_lba_range_requires_actual_completion', 'sync_extent_exceeding_capacity_refused', 'sync64_out_of_range_zero_count_refused', 'sync_immed_sync_nv_and_reserved_flags_refused_exhaustively', 'sync_group_and_control_refused', 'sync_exact_cdb_length_required', 'sync_no_payload_or_dma_direction_allowed', 'cache_current_default_dbd_writeback_and_no_mutable_policy', 'read_flags_never_claim_unimplemented_physical_cache_semantics', 'read6_10_12_16_all_bounded_counts_one_through_sixteen', 'read_full_64k_final_disk_span_and_one_block_overrun', 'read_64k_cap_exact_cpu_span_and_null_refused', 'read_multiblock_direction_contract_unchanged', 'write10_16_all_bounded_counts_payload_untouched', 'write_64k_entire_span_inside_ntfs_fence_and_fua_preserved', 'write_64k_cap_exact_cpu_span_and_null_refused', 'count_multiplication_wrap_and_large_32bit_counts_refused', 'cpu_address_span_wrap_refused_before_worker_pointer_arithmetic', 'system_write10_16_all_bounded_counts_and_fua_preserved_without_payload_mutation', 'system_entire_span_fits_one_gib_prefix_or_is_rejected_before_any_command', 'system_partition_tail_gap_gpt_neighbors_and_other_partitions_are_write_protected']
def main():
 p=argparse.ArgumentParser();p.add_argument('--out',type=Path,required=True);a=p.parse_args()
 if not os.environ.get('N976N_RAM_SCRATCH_PATH'):raise SystemExit('run through tools/ram_scratch.py')
 a.out.mkdir(parents=True,exist_ok=False);start=time.monotonic()
 binary=Path(os.environ['N976N_RAM_SCRATCH_PATH'])/('ufs-scsi-'+str(os.getpid()))
 source=['N976nUfsSystem.h','N976nUfsNtfsExpected.h','N976nUfsCore.h','N976nUfsScsi.c','N976nUfsScsi.h','tests/scsi_cases.c','tests/test_scsi.py']
 cmd=['clang','-std=c11','-O1','-Wall','-Wextra','-Werror','-Wno-misleading-indentation','-fsanitize=address,undefined','-fno-sanitize-recover=all','-I',str(ROOT),str(ROOT/'N976nUfsScsi.c'),str(ROOT/'tests/scsi_cases.c'),'-o',str(binary)]
 b=subprocess.run(cmd,text=True,capture_output=True,timeout=60);(a.out/'compile.log').write_text(b.stdout+b.stderr)
 checks=[];passed=False
 if b.returncode==0:
  r=subprocess.run([str(binary)],text=True,capture_output=True,timeout=60,env={**os.environ,'UBSAN_OPTIONS':'halt_on_error=1','ASAN_OPTIONS':'abort_on_error=1'})
  (a.out/'run.log').write_text(r.stdout+r.stderr);checks=r.stdout.splitlines();passed=r.returncode==0 and checks==REQUIRED
 binary.unlink(missing_ok=True)
 report={'milestone':'SEC89 UFS PERF5','passed':passed,'checks':checks,'required_cases':REQUIRED,'source_sha256':{str((ROOT/s).relative_to(ROOT.parents[1])):hashlib.sha256((ROOT/s).read_bytes()).hexdigest() for s in source},'hardware_verified':False,'elapsed_seconds':time.monotonic()-start,'scope':'actual SEC86 pure SCSI planner; bounded 64KiB OS spans with unchanged 4KiB hardware commands; independent WCE1 write/flush/cache wire-format and refusal oracles, including complete flag and CDB-length scans. No runtime arming, device completion, durability or Windows enumeration proof'}
 (a.out/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report));return 0 if passed else 1
if __name__=='__main__':raise SystemExit(main())
